from string import Template

class Post:
    def __init__(self, pk, title, is_published):
        self.pk, self.title, self.is_published = pk, title, is_published

POSTS = [Post(1, "Hello Django", True), Post(2, "Draft idea", False), Post(3, "Views 101", True)]
TEMPLATE = Template("<h1>$title</h1><ul>$items</ul>")

def render(template, context):                        # the template: HOW to show it
    items = "".join(f"<li>{p.title}</li>" for p in context["posts"])
    return template.substitute(title=context["title"], items=items)

def post_list(request):                               # the view: WHAT to show
    posts = [p for p in POSTS if p.is_published]
    context = {"posts": posts, "title": "Blog"}
    return {"status": 200, "body": render(TEMPLATE, context)}

response = post_list({"path": "/blog/"})
print(response["status"], response["body"])
